"""Validate and replay only the native VLCS run generated by this experiment."""

from collections import defaultdict
import csv
import json
from pathlib import Path

from experiments.delayed_feedback.run import sha256


def rows(path):
    with path.open(newline="", encoding="utf-8") as stream:
        return list(csv.DictReader(stream))


class NativeTrace:
    def __init__(self, folder, seed):
        folder = Path(folder)
        self.hashes = {name: sha256(folder / name) for name in (
            "settings.json", "result.json", "batches.csv", "feedback.csv", "updates.csv")}
        self.settings = json.loads((folder / "settings.json").read_text())
        result = json.loads((folder / "result.json").read_text())
        for record in (self.settings, result):
            if (record.get("method") != "VLCS-calibration" or record.get("dataset") != "VLCS"
                    or record.get("variant") != "simatta_original" or record.get("seed") != seed
                    or record.get("delay") != 0):
                raise ValueError("Wrong native VLCS reference identity")
        if self.settings["batch_size"] != 32:
            raise ValueError("Reference batch must be 32")
        self.batches = rows(folder / "batches.csv")
        self.steps = len(self.batches)
        if not self.steps:
            raise ValueError("Empty reference")
        self.bounds, domains = [], []
        offset = 0
        for step, row in enumerate(self.batches):
            size = int(row["samples"])
            if (int(row["step"]) != step or int(row["seed"]) != seed or int(row["delay"]) != 0
                    or not 1 <= size <= 32):
                raise ValueError("Invalid native batch sequence")
            if not domains or domains[-1] != row["domain"]:
                domains.append(row["domain"])
            self.bounds.append((offset, offset + size))
            offset += size
        if domains != ["LabelMe", "SUN09", "VOC2007"]:
            raise ValueError("Wrong VLCS target order")
        self.records = rows(folder / "feedback.csv")
        self.queries = defaultdict(list)
        seen = set()
        previous_step = -1
        for index, row in enumerate(self.records):
            step, sample = int(row["query_step"]), int(row["sample_id"])
            if not 0 <= step < self.steps or step < previous_step:
                raise ValueError("Invalid query clock")
            start, end = self.bounds[step]
            if (sample in seen or not start <= sample < end or int(row["anchor_index"]) != index
                    or int(row["due_step"]) != step or int(row["return_step"]) != step
                    or row["query_domain"] != self.batches[step]["domain"]
                    or row["return_domain"] != row["query_domain"]):
                raise ValueError("Invalid D=0 feedback record")
            seen.add(sample)
            previous_step = step
            self.queries[step].append(row)
        for step, batch in enumerate(self.batches):
            if (len(self.queries[step]) != int(batch["new_queries"])
                    or len(self.queries[step]) != int(batch["new_returns"])):
                raise ValueError("Query/return counts do not match batches")
        self.first_return = min((int(row["return_step"]) for row in self.records), default=None)
        self.old_updates = [0] * self.steps
        with (folder / "updates.csv").open(newline="", encoding="utf-8") as stream:
            last = -1
            for row in csv.DictReader(stream):
                step = int(row["step"])
                if (not 0 <= step < self.steps or step < last
                        or int(row["iteration"]) != self.old_updates[step]
                        or self.first_return is None or step < self.first_return):
                    raise ValueError("Invalid original update sequence")
                self.old_updates[step] += 1
                last = step
        self.total = sum(self.old_updates)
        self.slow, self.fast = list(self.old_updates), [0] * self.steps
        self.fast_enabled, self.fast_total = False, 0
        if (result["queried"] != len(self.records) or result["returned"] != len(self.records)
                or result["slow_updates"] != self.total):
            raise ValueError("Reference costs do not match recorded events")

    def verify_feedback(self, actual):
        keys = ("sample_id", "anchor_index", "query_step", "query_domain", "due_step",
                "return_step", "return_domain")
        if len(actual) != len(self.records):
            raise ValueError("Feedback count changed")
        for left, right in zip(actual, self.records):
            if any(str(left[key]) != right[key] for key in keys):
                raise ValueError("Feedback schedule changed")
